mapper.select:
SELECT p.id, p.tenant_id AS tenantId, p.position_code AS positionCode, p.position_name AS positionName, p.position_level AS positionLevel, ( SELECT COUNT(*) FROM iam_employee e WHERE e.position_id = p.id AND e.deleted = 0 AND e.tenant_id = p.tenant_id ) AS employeeCount, p.status, p.sort_no AS sortNo, p.remark FROM iam_position p WHERE p.deleted = 0 AND p.tenant_id = #{spec.tenantId}
AND 1 = 0
OR p.id IN
#{positionId}
OR EXISTS ( SELECT 1 FROM iam_employee e INNER JOIN iam_user u ON u.employee_id = e.id AND u.deleted = 0 INNER JOIN iam_user_role ur ON ur.user_id = u.id AND ur.deleted = 0 WHERE e.position_id = p.id AND e.deleted = 0 AND e.tenant_id = p.tenant_id AND ur.role_id IN
#{roleId}
)
AND 1 = 0
ORDER BY p.sort_no ASC, p.id ASC
